// Sorguya Qwen3'un talimat onekini ekle.
//
// Neden burada ve neden sabit: onek olcumun parcasi. eval_rag.py bu metinle
// olctu (r@5 0,636); n8n baska bir metin gonderirse sunumda soyledigimiz
// sayi ile sistemin yaptigi is ayrisir. Degistirilecekse IKISI BIRDEN.
const GOREV = "Given a developer's problem statement, retrieve the GitHub repository that solves it";

const sorgu = String($json.sorgu || '').trim();

// Bos sorgu bir is sonucu degil, bozuk bir cagri: ajan zorunlu alani
// doldurmamis demektir. Bu yuzden {ok:false} donmuyoruz, ATIYORUZ -
// hata ajanin gozlemine dusuyor ve ajan yeniden deneyebiliyor.
if (!sorgu) {
  throw new Error("repo_ara: 'sorgu' alani bos geldi. Kullanicinin aradigi islevi yaz.");
}

return [{ json: {
  sorgu: sorgu,
  gomme_metni: "Instruct: " + GOREV + "\nQuery:" + sorgu
} }];

// Iki is: (1) Ollama vektorunu pgvector bicimine cevir, (2) filtreleri
// DOGRULAYIP sorgu metnini kur.
//
// SQL neden burada kuruluyor: vektor 4096 eleman ve icinde virgul var;
// n8n'in queryReplacement'i virgulden boldugu icin vektorun yanina ikinci
// bir parametre konamiyor. Filtreler bu yuzden metne gomuluyor - ama ASLA
// dogrulanmadan: dil beyaz liste regexinden geciyor (tirnak karakteri
// gecemez) ve tirnaklari ikileniyor, rozet ise KAPALI listeden secilyor.
// Vektor tek parametre olarak $1'de kaliyor.
const BOYUT = 4096;
// 2026-09-11 | 15 -> 20. Sarp sorgu basina 10'lu liste istedi; ajan alakasiz
// olanlari eledigi icin 10'a ulasmak adina PAY gerekiyor.
// 2026-09-12 | `adet` ile AZALTILABILIR hale geldi. Sebep olculdu: yigin
// modunda uc arama x 20 satir = 60 satir (~4.200 token) ve model o yiginin
// icinde plani kaybediyordu. Yigin modunda bilesen basina 8 istenir.
// Tavan yine 20: ajan daha fazlasini isterse kirpilir, daha azini isterse
// saygi gosterilir, sacma bir deger gelirse varsayilana duser.
// 2026-09-12 | 20 -> 12. `aciklama` alani eklenince satir basina ~140
// karakter daha gidiyor; 20 satir modeli boguyor ve on madde yerine
// BES madde yaziyordu (olculdu: 61633, 61636, 61644, dogrulama kosusu).
// 12 = istenen 10 madde + 2 eleme payi.
// 2026-09-12 | 12 -> 10. SECIM ISI MODELDEN ALINDI. Istemde 'TAM 10 al'
// kurali ALTI yerde yaziliydi ve model yine bes madde yaziyordu
// (olculdu: uc soru, ucunde de tam 5). Elemeyi model yapmayinca is
// 'gelenin hepsini yaz'a donuyor - bu ise tutuyor.
const VARSAYILAN = 10;
const istenen = parseInt($('Arac Cagrildi').first().json.adet, 10);
const LIMIT = (Number.isFinite(istenen) && istenen >= 1)
  ? Math.min(istenen, VARSAYILAN)
  : VARSAYILAN;

const yanit = $input.first().json;
const v = (yanit.embeddings && yanit.embeddings[0]) || yanit.embedding;

if (!Array.isArray(v)) {
  throw new Error('Ollama vektor dondurmedi: ' + JSON.stringify(yanit).slice(0, 200));
}

// BOYUT KAPISI. Yanlis gomme modeli kullanilirsa Postgres zaten hata verir,
// ama mesaji ("expected 4096 dimensions, not 1024") n8n loglarinda kaybolur.
if (v.length !== BOYUT) {
  throw new Error('Vektor boyutu ' + v.length + ', beklenen ' + BOYUT +
                  '. Gomme modeli indeksi kuran modelle ayni mi?');
}

// --- FILTRELER ---------------------------------------------------------
const giris = $('Arac Cagrildi').first().json;
const kosullar = [];

// 2026-09-12 | "HEPSI" DEMENIN ON YOLU. Model bu alana "Heps", "HEPSI",
// "Hepsi", "hepsı", "all" yaziyor; kati esitlik yalnizca birini kabul edip
// digerlerinde CAGRIYI HATAYLA dusuruyordu (calisma 61638: dil="Heps",
// kullaniciya "Heps ifadesi kullanilamaz" diye bir hata metni gitti).
// Ayni tuzak sayim aracinda da cikmisti; cozum orada da kodda idi.
function hepsiMi(x) {
  const t = String(x == null ? '' : x).trim().toUpperCase();
  return t === '' || t.startsWith('HEPS') || t === 'ALL' || t === 'TUMU';
}

const dil = String(giris.dil || '').trim();
if (!hepsiMi(dil)) {
  // Beyaz liste: tirnak, noktali virgul, bosluk disi hicbir isaret gecemez.
  if (!/^[A-Za-z0-9+#.\- ]{1,30}$/.test(dil)) {
    throw new Error("repo_ara: 'dil' gecersiz: " + dil.slice(0, 40));
  }
  kosullar.push("r.language ILIKE '" + dil.replace(/'/g, "''") + "'");
}

const ROZETLER = { GREEN: 'GREEN', AMBER: 'AMBER', RED: 'RED',
                   YESIL: 'GREEN', SARI: 'AMBER', KIRMIZI: 'RED' };
const rozetHam = String(giris.rozet || '').trim().toUpperCase();
if (!hepsiMi(rozetHam)) {
  const r = ROZETLER[rozetHam];
  if (!r) {
    throw new Error("repo_ara: 'rozet' GREEN/AMBER/RED olmali, gelen: " +
                    rozetHam.slice(0, 20));
  }
  kosullar.push("r.badge_today = '" + r + "'");
}

// OLGUNLUK (12.09). is_mature = DS21_Final_v2.py STEP 13.6 kurali:
// ilk-son commit arasi >= 52 hafta VE >= 50 commit VE bir haftada >= 3 katkici.
// Gecmisi olmayan repo olgun SAYILMAZ; NULL'lar da disarida kalir.
// Rozet gibi KAPALI LISTE: ajan ne yazarsa yazsin SQL'e yalnizca bu iki
// ifadeden biri girer.
const KOKLU = { EVET: 'r.is_mature IS TRUE', HAYIR: 'r.is_mature IS NOT TRUE' };
const kokluHam = String(giris.koklu || '').trim().toUpperCase();
if (!hepsiMi(kokluHam)) {
  const k = KOKLU[kokluHam];
  if (!k) {
    throw new Error("repo_ara: 'koklu' EVET/HAYIR/HEPSI olmali, gelen: " +
                    kokluHam.slice(0, 20));
  }
  kosullar.push(k);
}

const filtre = kosullar.length ? ('\n  AND ' + kosullar.join('\n  AND ')) : '';

const ROZET_IFADE =
  "CASE r.badge_today WHEN 'GREEN' THEN '\ud83d\udfe2' " +
  "WHEN 'AMBER' THEN '\ud83d\udfe1' ELSE '\ud83d\udd34' END";

// IKI SIRALAMA, IKI AMAC:
//   ic sorgu  -> ORDER BY embedding <=> $1  : hangi 15 repo ILGILI
//   dis sorgu -> ORDER BY aktiflik_yuzde    : hangi SIRAYLA gosterilecek
// Gosterim sirasi modele birakilmiyor; modelden siralama istemek bu
// oturumda uc kez basarisiz oldu.
const sql =
  "SELECT * FROM (\n" +
  "SELECT r.full_name,\n" +
  "       ROUND(MAX(1 - (v.embedding <=> $1::vector))::numeric, 4) AS benzerlik,\n" +
  "       " + ROZET_IFADE + " AS rozet,\n" +
  "       '**[' || r.full_name || '](https://github.com/' || r.full_name || ')** '\n" +
  "         || " + ROZET_IFADE + "\n" +
  "         || ' \u00b7 %' || ROUND(r.p_active_today * 100)\n" +
  "         || ' \u00b7 \u2b50 ' || replace(to_char(stars, 'FM999,999,999'), ',', '.')\n" +
  "         || COALESCE(' \u00b7 ' || language, '')\n" +
  "         AS satir,\n" +
  "       ROUND(r.p_active_today * 100) AS aktiflik_yuzde,\n" +
  "       r.is_mature, r.ai_category,\n" +
  // 2026-09-12 | ACIKLAMA ALANI. Arac bugune kadar reponun NE YAPTIGINI hic
  // gondermiyordu: modele yalnizca ad, rozet, yildiz ve dil gidiyordu. Her
  // gerekce repo ADINDAN uyduruluyordu (61625: on maddenin onunde ayni cumle
  // + verimizde hic gecmeyen "guvenlik" iddiasi. 61627: kurulum adimlari
  // uyduruldu, oysa repo Docker ile kuruluyor).
  // doc_primary bicimi: "<full_name> <aciklama> Topics: ...". Basindaki adi
  // ve Topics kuyrugunu kesiyoruz. Ters bolu kullanmamak icin chr() ile.
  // NOT: burada regexp_replace KULLANMA. Desendeki $ isareti n8n Postgres
  // dugumunun $1 parametre yer tutucusuyla cakisiyor ve sorgu
  // "Syntax error near VERI_YOK" ile dusuyor (olculdu: 61705, 61707, 61708).
  "       left(trim(split_part(replace(replace(substr(r.doc_primary,\n" +
  "            length(r.full_name)+2), chr(10), ' '), chr(13), ' ')," +
  "            'Topics:', 1)), 150) AS aciklama_en\n" +
  "FROM (\n" +
  "    SELECT full_name, embedding FROM repos WHERE embedding IS NOT NULL\n" +
  "    UNION ALL\n" +
  "    SELECT full_name, embedding FROM repo_govde\n" +
  ") v\n" +
  "JOIN repos r USING (full_name)\n" +
  "WHERE r.badge_today <> 'VERI_YOK'" + filtre + "\n" +
  "GROUP BY r.full_name\n" +
  "ORDER BY MAX(1 - (v.embedding <=> $1::vector)) DESC\n" +
  "LIMIT " + LIMIT + "\n" +
  ") q\n" +
  "ORDER BY aktiflik_yuzde DESC NULLS LAST";

return [{ json: {
  vektor: '[' + v.join(',') + ']',
  sql: sql,
  uygulanan_filtre: kosullar.length ? kosullar.join(' AND ') : 'yok',
  sorgu: $('Sorguyu Hazirla').first().json.sorgu
} }];

// SOZLESME DUGUMU - bu workflow'un ciktisi budur.
// Ajan bu satirlari okuyup cevabi yazacak, o yuzden:
//   - vektor ve ham float gonderilmiyor (baglam israfi)
//   - alan adlari kendini anlatiyor
//   - 0 sonuc bir HATA degil, gecerli bir cevap
const satirlar = $input.all();

if (satirlar.length === 0) {
  return [{ json: { ok: true, sonuc_sayisi: 0, sonuclar: [],
                    not: 'Bu tarife uyan repo bulunamadi.' } }];
}

// ⚠️ link / rozet / yildiz / yuzde BILEREK GONDERILMIYOR.
// Onlar ayrica gonderilirken model `satir`i kopyalamak yerine parcalardan
// yeniden kuruyor ve kuyrugu ("· %18 · ⭐ 2.194") dusuruyordu (calisma 57682).
// Hepsi zaten `satir` icinde. full_name yalnizca kapanis cumlesi icin duruyor.
// Siralama SQL'de yapiliyor (dis ORDER BY aktiflik_yuzde DESC).
// Burada TEKRAR siralamiyoruz: ayni kurali iki yerde tutmak, birini
// degistirip digerini unutmanin kisa yoludur.

// `no`: ajanin KAC madde yazdigini takip edebilmesi icin. Olculdu (11.09):
// arac her seferinde 20 satir donduruyor ama ajan ortalama 7 madde yaziyordu;
// sayilabilir bir isaret olmadan "10 yaz" talimati tutmuyor.
// `bilesen`: bu satirin HANGI aramadan geldigi. Yigin modunda ajan uc ayri
// arama yapiyor ve sonuclari tek havuzda birlestirip son aramanin listesini
// yaziyordu (olculdu: 61170, 61176). Etiket satirin uzerinde olunca gruplama
// hatirlamaya degil VERIYE dayaniyor.
// ---- ZAYIF ESLESME KAPISI (13.09, DS_BULGULAR B24) ----------------------
// SQL her zaman en yakin 10 repoyu dondurur - "Istanbul-Berlin ucuz ucak
// bileti" icin de. Olculdu (sunum/kosum/prob_negatif_kontrol.py, 354 sinav
// sorgusu + 12 konu disi sorgu): en iyi benzerlik 0.58 altindaysa 12 konu
// disi sorgunun 11'i yakalaniyor, sinav sorgularinin yalniz 3'u kesiliyor ve
// o 3'unde dogru repo zaten ilk 10'da degildi.
// Satirlar AKTIFLIGE gore sirali geldigi icin en iyi benzerlik ilk satir
// DEGIL, hepsinin en buyugu.
const ESIK = 0.58;
const enIyi = Math.max(...satirlar.map(x => Number(x.json.benzerlik) || 0));
if (enIyi < ESIK) {
  return [{ json: { ok: true, sonuc_sayisi: 0, sonuclar: [], zayif_eslesme: true,
                    en_yuksek_benzerlik: enIyi,
                    not: 'Arsivde bu tarife yeterince yakin repo yok. Bulunamadigini ' +
                         'soyle; liste, uyari satiri ve oneri YAZMA.' } }];
}

const BILESEN = $('Sorguyu Hazirla').first().json.sorgu;

return satirlar.map((x, i) => ({ json: {
  no:          i + 1,
  bilesen:     BILESEN,
  satir:       x.json.satir,
  full_name:   x.json.full_name,
  koklu_proje: x.json.is_mature,
  kategori:    x.json.ai_category,
  benzerlik:   x.json.benzerlik,
  // GEREKCENIN DAYANAGI: reponun GitHub'daki kendi tanimi.
  // Alan adinda 'en' var: model bunun INGILIZCE oldugunu ve CEVIRMESI
  // gerektigini alan adindan da gorsun. Olculdu: sade 'aciklama' adiyla
  // Ingilizce metni oldugu gibi yapistirdi.
  aciklama_en: x.json.aciklama_en || ''
} }));
